11	const app = express();
12	
13	// ── Security: CORS — restrict to localhost origins ────────────────────────────
14	const ALLOWED_ORIGINS = new Set([
15	  'http://localhost:3847',
16	  'http://localhost:5173',   // Vite dev
17	  'http://localhost:3000',
18	  'http://localhost:8080',
19	  'http://127.0.0.1:3847',
20	  'http://127.0.0.1:5173',
21	  'http://127.0.0.1:3000',
22	  'http://127.0.0.1:8080',
23	]);
24	
25	app.use((req, res, next) => {
26	  const origin = req.headers.origin;
27	  if (origin && ALLOWED_ORIGINS.has(origin)) {
28	    res.header('Access-Control-Allow-Origin', origin);
29	  } else if (!origin) {
30	    // Same-origin or non-browser client — no CORS header needed
31	  }
32	  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
33	  res.header('Access-Control-Allow-Headers', 'Content-Type');
34	  if (req.method === 'OPTIONS') return res.sendStatus(204);
35	  next();
36	});
37	
38	// ── Security: Localhost-only guard ────────────────────────────────────────────
39	app.use((req, res, next) => {
40	  // Webhook triggers are accessible externally (validated by secret)
41	  if (req.path.startsWith('/api/webhooks/trigger/')) return next();
42	  const ip = req.ip || req.connection?.remoteAddress || '';
43	  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
44	  if (!isLocal) {
45	    return res.status(403).json({ error: 'Polyglot is local-only' });
46	  }
47	  next();
48	});
49	
50	// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
51	const rateLimitMap = new Map();
52	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
53	const RATE_LIMITS = {
54	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
55	  write: 60,   // file writes, creates, deletes — 60/min
56	  read: 200,   // reads, listings — 200/min
57	};
58	
59	function rateLimit(tier) {
60	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
61	  return (req, res, next) => {
62	    const key = `${tier}:${req.ip}`;
63	    const now = Date.now();
64	    let entry = rateLimitMap.get(key);
65	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
66	      entry = { start: now, count: 0 };
67	      rateLimitMap.set(key, entry);
68	    }
69	    entry.count++;
70	    if (entry.count > max) {
71	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
72	    }
73	    next();
74	  };
75	}
76	
77	// Cleanup stale entries every 5 minutes
78	setInterval(() => {
79	  const now = Date.now();
80	  for (const [key, entry] of rateLimitMap) {
81	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
82	  }
83	}, 300_000);
84	
85	// ── Security: Helmet-like headers ────────────────────────────────────────────
86	app.use((req, res, next) => {
87	  res.setHeader('X-Content-Type-Options', 'nosniff');
88	  res.setHeader('X-Frame-Options', 'DENY');
89	  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
90	  next();
91	});
