190	function validateProjectId(req, res, next) {
191	  const projectPath = resolveProjectPath(req.params.id);
192	  if (!projectPath) {
193	    return res.status(400).json({ error: 'Invalid project ID' });
194	  }
195	  // Verify it's within allowed project directories
196	  const config = loadConfig();
197	  const allowedRoots = [
198	    CLAUDE_DIR,
199	    ...config.projectDirs.map(d => path.resolve(d.replace(/^~/, HOME))),
200	  ];
201	  const isAllowed = allowedRoots.some(root =>
202	    projectPath === root || projectPath.startsWith(root + path.sep)
203	  );
204	  if (!isAllowed) {
205	    return res.status(403).json({ error: 'Project outside allowed directories' });
206	  }
207	  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
208	    return res.status(404).json({ error: 'Project directory not found' });
209	  }
210	  req.projectPath = projectPath;
211	  next();
212	}
