19	function getDb() {
20	  if (_db) return _db;
21	  fs.mkdirSync(DB_DIR, { recursive: true });
22	  _db = new Database(DB_PATH);
23	  _db.pragma('journal_mode = WAL');
24	  _db.pragma('foreign_keys = ON');
25	  _db.pragma('busy_timeout = 5000');
