448	  function readJsonFile(filePath) {
449	    if (fs.existsSync(filePath)) return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
450	    if (fs.existsSync(filePath + '.migrated')) {
451	      console.warn(`[db:migrate] Recovering from ${filePath}.migrated (DB was recreated)`);
452	      return JSON.parse(fs.readFileSync(filePath + '.migrated', 'utf-8'));
453	    }
454	    return null;
455	  }
