459	    if (!actual) return [];
460	    if (actual.endsWith('.migrated')) console.warn(`[db:migrate] Recovering from ${actual} (DB was recreated)`);
461	    return fs.readFileSync(actual, 'utf-8').split('\n').filter(Boolean).map(line => {
462	      try { return JSON.parse(line); } catch { return null; }
463	    }).filter(Boolean);
464	  }
