1096	// CHANGE LOG — auto-snapshot before every write for revert capability
1097	// ═══════════════════════════════════════════════════════════════════════════
1098	
1099	function createChangeLog(db) {
1100	  db.exec(`
1101	    CREATE TABLE IF NOT EXISTS db_change_log (
1102	      id         INTEGER PRIMARY KEY AUTOINCREMENT,
1103	      tableName  TEXT NOT NULL,
1104	      rowKey     TEXT NOT NULL,
1105	      action     TEXT NOT NULL,
1106	      oldData    TEXT,
1107	      newData    TEXT,
1108	      changedAt  TEXT NOT NULL DEFAULT (datetime('now')),
1109	      reverted   INTEGER DEFAULT 0
1110	    );
1111	    CREATE INDEX IF NOT EXISTS idx_change_log_table ON db_change_log(tableName);
1112	    CREATE INDEX IF NOT EXISTS idx_change_log_time ON db_change_log(changedAt DESC);
1113	  `);
1114	}
1115	
1116	function logChange(tableName, rowKey, action, oldData, newData) {
1117	  stmt('INSERT INTO db_change_log (tableName, rowKey, action, oldData, newData, changedAt) VALUES (?,?,?,?,?,?)')
1118	    .run(tableName, String(rowKey), action, oldData ? JSON.stringify(oldData) : null, newData ? JSON.stringify(newData) : null, new Date().toISOString());
1119	}
1120	
1121	function getChanges(tableName, limit = 100) {
1122	  if (tableName) {
1123	    return stmt('SELECT * FROM db_change_log WHERE tableName = ? ORDER BY changedAt DESC LIMIT ?').all(tableName, limit).map(parseChange);
1124	  }
1125	  return stmt('SELECT * FROM db_change_log ORDER BY changedAt DESC LIMIT ?').all(limit).map(parseChange);
1126	}
1127	
1128	function parseChange(r) {
1129	  return {
1130	    ...r,
1131	    oldData: r.oldData ? JSON.parse(r.oldData) : null,
1132	    newData: r.newData ? JSON.parse(r.newData) : null,
1133	    reverted: !!r.reverted,
1134	  };
1135	}
