1137	function getPrimaryKeyColumn(tableName) {
1138	  const info = getDb().prepare(`PRAGMA table_info("${tableName}")`).all();
1139	  const pk = info.find(c => c.pk === 1);
1140	  return pk ? pk.name : null;
1141	}
1142	
1143	function updateRow(tableName, pkValue, updates) {
1144	  const d = getDb();
1145	  const pkCol = getPrimaryKeyColumn(tableName);
1146	  if (!pkCol) throw new Error(`No primary key found for table ${tableName}`);
1147	
1148	  // Snapshot old data
1149	  const oldRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1150	  if (!oldRow) throw new Error(`Row not found: ${pkCol}=${pkValue}`);
1151	
1152	  // Build UPDATE
1153	  const setClauses = [];
1154	  const values = [];
1155	  for (const [col, val] of Object.entries(updates)) {
1156	    if (col === pkCol) continue; // Don't update PK
1157	    setClauses.push(`"${col}" = ?`);
1158	    values.push(val === undefined ? null : val);
1159	  }
1160	  if (setClauses.length === 0) throw new Error('No fields to update');
1161	
1162	  values.push(pkValue);
1163	  d.prepare(`UPDATE "${tableName}" SET ${setClauses.join(', ')} WHERE "${pkCol}" = ?`).run(...values);
1164	
1165	  // Get new data
1166	  const newRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1167	
1168	  // Log the change
1169	  logChange(tableName, pkValue, 'update', oldRow, newRow);
1170	
1171	  return newRow;
1172	}
1173	
1174	function revertChange(changeId) {
1175	  const d = getDb();
1176	  const change = d.prepare('SELECT * FROM db_change_log WHERE id = ?').get(changeId);
1177	  if (!change) throw new Error('Change not found');
1178	  if (change.reverted) throw new Error('Already reverted');
1179	  if (!change.oldData) throw new Error('No old data to revert to');
1180	
1181	  const oldData = JSON.parse(change.oldData);
1182	  const pkCol = getPrimaryKeyColumn(change.tableName);
1183	  if (!pkCol) throw new Error(`No primary key for table ${change.tableName}`);
1184	
1185	  // Get current row for forward-log
1186	  const currentRow = d.prepare(`SELECT * FROM "${change.tableName}" WHERE "${pkCol}" = ?`).get(change.rowKey);
1187	
1188	  // Restore all columns from old data
1189	  const setClauses = [];
1190	  const values = [];
1191	  for (const [col, val] of Object.entries(oldData)) {
1192	    if (col === pkCol) continue;
1193	    setClauses.push(`"${col}" = ?`);
1194	    values.push(val === undefined ? null : val);
1195	  }
1196	  values.push(change.rowKey);
1197	  d.prepare(`UPDATE "${change.tableName}" SET ${setClauses.join(', ')} WHERE "${pkCol}" = ?`).run(...values);
1198	
1199	  // Mark original change as reverted
1200	  d.prepare('UPDATE db_change_log SET reverted = 1 WHERE id = ?').run(changeId);
1201	
1202	  // Log the revert as its own change
1203	  logChange(change.tableName, change.rowKey, 'revert', currentRow, oldData);
1204	
1205	  return { ok: true, restoredData: oldData };
1206	}
1207	
1208	function deleteRow(tableName, pkValue) {
1209	  const d = getDb();
1210	  const pkCol = getPrimaryKeyColumn(tableName);
1211	  if (!pkCol) throw new Error(`No primary key found for table ${tableName}`);
1212	
1213	  const oldRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1214	  if (!oldRow) throw new Error(`Row not found: ${pkCol}=${pkValue}`);
1215	
1216	  d.prepare(`DELETE FROM "${tableName}" WHERE "${pkCol}" = ?`).run(pkValue);
1217	  logChange(tableName, pkValue, 'delete', oldRow, null);
1218	
1219	  return { ok: true };
1220	}
