317	/**
318	 * Recompute experience for every agent in the registry and write the result
319	 * back to registry.json. Called nightly by Roster (Phase 5 cron) and on
320	 * demand via POST /api/hr/recompute-experience.
321	 *
322	 * @param {object} orgModule — the src/org.js module (injected to avoid circular dep)
323	 * @returns {object} Summary { updated, errors, durationMs }
324	 */
325	function recomputeAllExperience(orgModule) {
326	  const started = Date.now();
327	  const allRuns = loadAgentRuns();
328	  const registry = orgModule.loadRegistry();
329	  const agentIds = Object.keys(registry.agents || {});
330	
331	  let updated = 0;
332	  const errors = [];
333	
334	  for (const id of agentIds) {
335	    try {
336	      const record = registry.agents[id];
337	      const profile = computeExperience(record, allRuns);
338	      registry.agents[id] = { ...record, ...profile };
339	      updated++;
340	    } catch (err) {
341	      errors.push({ id, error: err.message });
342	    }
343	  }
344	
345	  orgModule.saveRegistry(registry);
346	
347	  return {
348	    updated,
349	    total: agentIds.length,
350	    errors,
351	    durationMs: Date.now() - started,
352	  };
353	}
354	
355	module.exports = {
356	  LEVEL_THRESHOLDS,
357	  DEFAULT_WEIGHTS,
358	  loadWeights,
359	  levelForYoE,
360	  readAgentFileStats,
361	  loadAgentRuns,
362	  computeRunStats,
363	  countPatternsContributed,
364	  countAntipatternsTriggered,
365	  computeSkillVector,
366	  identifyWeaknesses,
367	  computeExperience,
368	  recomputeAllExperience,
369	};
