1	// Budget checker for agent bodies.
2	// Invoked by the PUT handler before atomic write; mirrors the budgets defined
3	// in scripts/compactor/compact.mjs. Per-agent frontmatter overrides
4	// (compactor.budget_lines / compactor.budget_chars / compactor.allow_oversize)
5	// take precedence.
6	
7	const DEFAULTS = {
8	  _default: { lines: 400, chars: 16000 },
9	  rex: { lines: 700, chars: 28000 },
10	  arya: { lines: 700, chars: 28000 },
11	  vex: { lines: 300, chars: 12000 },
12	  zeph: { lines: 300, chars: 12000 },
13	};
14	
15	const WARN_FACTOR = 0.9;  // warn >=90%
16	const HARD_FACTOR = 1.1;  // reject >=110%
17	
18	function resolveBudget(agentId, frontmatter) {
19	  const fm = frontmatter?.compactor || {};
20	  const base = DEFAULTS[agentId] || DEFAULTS._default;
21	  return {
22	    lines: Number.isFinite(fm.budget_lines) ? fm.budget_lines : base.lines,
23	    chars: Number.isFinite(fm.budget_chars) ? fm.budget_chars : base.chars,
24	    allowOversize: Boolean(fm.allow_oversize),
25	  };
26	}
27	
28	function splitFrontmatter(content) {
29	  // Lightweight split — avoids requiring gray-matter at the hot path.
30	  const m = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
31	  if (!m) return { frontmatterText: '', body: content, hasFrontmatter: false };
32	  return { frontmatterText: m[1], body: m[2], hasFrontmatter: true };
33	}
34	
35	function tryParseFrontmatter(frontmatterText) {
36	  // Minimal YAML extraction: we only need the `compactor:` subtree. Avoid
37	  // pulling a full YAML parser into the hot path; the PUT handler can pass
38	  // a pre-parsed frontmatter object instead if available.
39	  const out = { compactor: {} };
40	  const lines = frontmatterText.split('\n');
41	  let inCompactor = false;
42	  for (const line of lines) {
43	    if (/^compactor:\s*$/.test(line)) { inCompactor = true; continue; }
44	    if (inCompactor) {
45	      if (/^\S/.test(line)) { inCompactor = false; continue; }
46	      const kv = line.match(/^\s+([a-z_]+):\s*(.+?)\s*$/i);
47	      if (kv) {
48	        const k = kv[1];
49	        let v = kv[2];
50	        if (v === 'true') v = true;
51	        else if (v === 'false') v = false;
52	        else if (/^-?\d+(\.\d+)?$/.test(v)) v = Number(v);
53	        else v = v.replace(/^['"]|['"]$/g, '');
54	        out.compactor[k] = v;
55	      }
56	    }
57	  }
58	  return out;
59	}
60	
61	function checkBudget({ agentId, content, frontmatter }) {
62	  const { body, frontmatterText } = splitFrontmatter(content);
63	  const fm = frontmatter || tryParseFrontmatter(frontmatterText);
64	  const budget = resolveBudget(agentId, fm);
65	  const bodyLines = body.split('\n').length;
66	  const bodyChars = body.length;
67	
68	  const violations = [];
69	  const warnings = [];
70	
71	  if (bodyLines > budget.lines * HARD_FACTOR) {
72	    violations.push({ kind: 'lines', actual: bodyLines, budget: budget.lines, limit: Math.round(budget.lines * HARD_FACTOR) });
73	  } else if (bodyLines > budget.lines * WARN_FACTOR) {
